  <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.4.0/addons/p5.dom.min.js"></script>
  <script src="sketch.js"></script>
</head>
<body>
</body>
</html>
```

Next, create a JavaScript file named `sketch.js` and add the following code:

```javascript
let sidesSlider;
let font;

function setup() {
  createCanvas(600, 400);
  sidesSlider = createSlider(3, 20, 3);
  sidesSlider.position(20, 20);
  textAlign(CENTER, CENTER);
}

function draw() {
  background(240);

  let sides = sidesSlider.value();
  translate(width / 2, height / 2);
  strokeWeight(4);
  stroke(50);
  fill(200);
  drawShape(sides);
}

function drawShape(sides) {
  let angle = TWO_PI / sides;
  let radius = min(width, height) / 3;
  beginShape();
  for (let i = 0; i < sides; i++) {
    let x = radius * cos(angle * i);
    let y = radius * sin(angle * i);
    vertex(x, y);
  }
  endShape(CLOSE);
}
```

In this example, we used p5.js and p5.dom.js to create a slider (knob) that controls the number of sides of a shape. The shape is drawn at the center of the canvas and has a dynamic number of sides based on the value of the slider. The slider's value ranges from 3 to 20 and, as its value changes, the shape changes accordingly.

To run the program, open the `index.html` file in your browser.
